      await adapter.generateSpeech('Hello', {
        voice: 'paul',
        speed: 1.2,
        format: 'wav'
      });

      expect(fetch).toHaveBeenCalledWith(
        'https://api.elevenlabs.io/v1/text-to-speech/5Q0t7uMcjvnagumLfvZi',
        expect.objectContaining({
          body: JSON.stringify({
            text: 'Hello',
            model_id: 'eleven_multilingual_v2',
            voice_settings: {
              stability: 0.5,
              similarity_boost: 0.8,
              voice_name: 'paul',
              speed: 1.2
            }
          })
        })
      );
      expect(result.format).toBe('wav');
    });

    it('should handle API error', async () => {
      const mockResponse = {
        ok: false,
        status: 401,
        json: vi.fn().mockResolvedValue({
          error: 'Invalid API key'
        })
      };
      (fetch as any).mockResolvedValue(mockResponse);

      await expect(adapter.generateSpeech('Hello')).rejects.toThrow();
    });
  });
});

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { ConfigManager, obfuscateKey, deobfuscateKey } from './configManager';

// Mock localStorage
const localStorageMock = {
  getItem: vi.fn(),
  setItem: vi.fn(),
  removeItem: vi.fn()
};

// Mock import.meta.env
