   // Check for localStorage availability
   function isLocalStorageAvailable() {
     try {
       const storage = window.localStorage;
       const test = '__test__';
       storage.setItem(test, test);
       storage.removeItem(test);
       return true;
     } catch {
       return false;
     }
   }
