/**
 * Type definitions for CodeBaseCartographer server
 */

export interface FileEvent {
  type: 'add' | 'change' | 'unlink';
  path: string;
  timestamp: number;
}

export interface FileChangeEvent {
  type: 'add' | 'change' | 'unlink';
  path: string;
  stats?: {
    size: number;
    mtime: Date;
  };
}

export interface FileContent {
  path: string;
  content: string;
  encoding: string;
}

export interface WriteOperation {
  path: string;
  oldContent: string | null;
  newContent: string;
  timestamp: number;
}

export interface ChangeRecord extends WriteOperation {
  id: string;
}

export interface Task {
  id: string;
  title: string;
  description: string;
  status: 'pending' | 'in_progress' | 'completed' | 'blocked';
  priority: 'low' | 'medium' | 'high' | 'critical';
  files: string[];
  dependencies: string[];
  createdAt: number;
  updatedAt: number;
}

export interface CreateTaskInput {
  title: string;
  description?: string;
  status?: Task['status'];
  priority?: Task['priority'];
  files?: string[];
  dependencies?: string[];
}

export interface UpdateTaskInput {
  title?: string;
  description?: string;
  status?: Task['status'];
  priority?: Task['priority'];
  files?: string[];
  dependencies?: string[];
}

export interface WebSocketMessage {
  type: 'file:changed' | 'file:added' | 'file:deleted' | 'task:updated' | 'error';
  data: unknown;
  timestamp: number;
}

export interface ErrorResponse {
  error: string;
  code?: string;
  details?: unknown;
}

export interface WatcherOptions {
  debounce?: number;
  ignored?: string[];
  persistent?: boolean;
  ignoreInitial?: boolean;
}

/**
 * fileWatcher.ts - Chokidar wrapper with .gitignore-aware path filtering
 *
 * Features:
 * - Debounced file events (500ms default)
 * - .gitignore-aware path filtering
 * - Event emission for add, change, unlink
 * - Support for custom ignore patterns
 */

import chokidar from 'chokidar';
import { parse } from 'path';
import { readFileSync } from 'fs';
import type { FSWatcher } from 'chokidar';
import type { FileEvent, FileChangeEvent, WatcherOptions } from './types.js';

export class FileWatcher {
  private watcher: FSWatcher | null = null;
  private eventQueue: Map<string, NodeJS.Timeout> = new Map();
  private debounceTime: number;
  private watchedPath: string;
  private eventCallbacks: Set<(event: FileEvent) => void> = new Set();
  private ignorePatterns: string[] = [];
  private gitignorePatterns: string[] = [];

  constructor(watchedPath: string, options: WatcherOptions = {}) {
    this.watchedPath = watchedPath;
    this.debounceTime = options.debounce ?? 500;
    this.ignorePatterns = options.ignored ?? [];
    this.loadGitignore();
  }

  /**
   * Load and parse .gitignore file if it exists
   */
  private loadGitignore(): void {
    try {
      const gitignorePath = `${this.watchedPath}/.gitignore`;
      const content = readFileSync(gitignorePath, 'utf-8');
      this.gitignorePatterns = content
        .split('\n')
        .map(line => line.trim())
        .filter(line => line && !line.startsWith('#'));
    } catch (error) {
      // .gitignore doesn't exist or can't be read - that's fine
      this.gitignorePatterns = [];
    }
  }

  /**
   * Check if a path should be ignored based on gitignore and custom patterns
   */
  private shouldIgnore(path: string): boolean {
    const basename = parse(path).base;

    // Check custom ignore patterns
    for (const pattern of this.ignorePatterns) {
      if (path.includes(pattern)) {
        return true;
      }
    }

    // Check gitignore patterns
    for (const pattern of this.gitignorePatterns) {
      if (pattern.includes('*')) {
        // Convert glob pattern to regex
        const regexPattern = pattern
          .replace(/\*/g, '.*')
          .replace(/\?/g, '.');
        const regex = new RegExp(regexPattern);
        if (regex.test(basename) || regex.test(path)) {
          return true;
        }
      } else if (path.endsWith(pattern) || basename === pattern) {
        return true;
      }
    }

    // Always ignore node_modules and .git
    if (path.includes('node_modules') || path.includes('.git')) {
      return true;
    }

    return false;
  }

  /**
   * Debounce file events to avoid multiple rapid-fire events
   */
  private debounceEvent(event: FileChangeEvent): void {
    const key = `${event.type}:${event.path}`;

    // Clear existing timeout for this path/event type
    const existingTimeout = this.eventQueue.get(key);
    if (existingTimeout) {
      clearTimeout(existingTimeout);
    }

    // Set new timeout
    const timeout = setTimeout(() => {
      this.emitEvent({
        type: event.type,
        path: event.path,
        timestamp: Date.now(),
      });
      this.eventQueue.delete(key);
    }, this.debounceTime);

    this.eventQueue.set(key, timeout);
  }

  /**
   * Emit event to all registered callbacks
   */
  private emitEvent(event: FileEvent): void {
    this.eventCallbacks.forEach(callback => {
      try {
        callback(event);
      } catch (error) {
        console.error('Error in file event callback:', error);
      }
    });
  }

  /**
   * Start watching the specified path
   */
  public start(): void {
    if (this.watcher) {
      throw new Error('Watcher is already running');
    }

    const allIgnored = [
      '**/node_modules/**',
      '**/.git/**',
      '**/dist/**',
      '**/build/**',
      ...this.ignorePatterns,
      ...this.gitignorePatterns,
    ];

    this.watcher = chokidar.watch(this.watchedPath, {
      ignored: allIgnored,
      persistent: true,
      ignoreInitial: true,
      awaitWriteFinish: {
        stabilityThreshold: 200,
        pollInterval: 100,
      },
    });

    this.watcher
      .on('add', (path) => {
        if (!this.shouldIgnore(path)) {
          this.debounceEvent({ type: 'add', path });
        }
      })
      .on('change', (path) => {
        if (!this.shouldIgnore(path)) {
          this.debounceEvent({ type: 'change', path });
        }
      })
      .on('unlink', (path) => {
        if (!this.shouldIgnore(path)) {
          this.debounceEvent({ type: 'unlink', path });
        }
      })
      .on('error', (error) => {
        console.error('File watcher error:', error);
      });

    // Wait for watcher to be ready
    this.watcher.on('ready', () => {
      console.log(`File watcher ready: watching ${this.watchedPath}`);
    });
  }

  /**
   * Stop watching
   */
  public stop(): void {
    if (this.watcher) {
      // Clear all pending debounced events
      this.eventQueue.forEach(timeout => clearTimeout(timeout));
      this.eventQueue.clear();

      this.watcher.close();
      this.watcher = null;
      console.log('File watcher stopped');
    }
  }

  /**
   * Register a callback for file events
   */
  public onFileEvent(callback: (event: FileEvent) => void): () => void {
    this.eventCallbacks.add(callback);

    // Return unsubscribe function
    return () => {
      this.eventCallbacks.delete(callback);
    };
  }

  /**
   * Get list of currently watched paths
   */
  public getWatchedPaths(): string[] {
    if (!this.watcher) {
      return [];
    }
    return Object.keys(this.watcher.getWatched());
  }

  /**
   * Check if watcher is currently running
   */
  public isRunning(): boolean {
    return this.watcher !== null;
  }
}

/**
 * fileOperator.ts - Safe file read/write operations
 *
 * Features:
 * - Safe read operations with error handling
 * - Write operations with automatic backup
 * - Path validation to ensure operations stay within watched directory
 * - Consistent error formatting
 */

import { readFileSync, writeFileSync, existsSync, mkdirSync, statSync } from 'fs';
import { dirname, resolve, relative, isAbsolute } from 'path';
import type { FileContent, ErrorResponse } from './types.js';

export class FileOperator {
  private basePath: string;

  constructor(basePath: string) {
    this.basePath = resolve(basePath);
  }

  /**
   * Validate that a path is within the watched directory
   * @throws Error if path is outside base directory or contains traversal attempts
   */
  public validatePath(path: string): string {
    const resolvedPath = isAbsolute(path) ? path : resolve(this.basePath, path);
    const relativePath = relative(this.basePath, resolvedPath);

    // Check for path traversal attempts
    if (relativePath.startsWith('..')) {
      throw this.createError(
        'Path traversal detected',
        'PATH_TRAVERSAL',
        { requestedPath: path, resolvedPath }
      );
    }

    // Ensure path is within base directory
    if (!resolvedPath.startsWith(this.basePath)) {
      throw this.createError(
        'Path is outside watched directory',
        'INVALID_PATH',
        { requestedPath: path, basePath: this.basePath }
      );
    }

    return resolvedPath;
  }

  /**
   * Read file content with error handling
   */
  public readFile(path: string): FileContent {
    try {
      const validatedPath = this.validatePath(path);

      if (!existsSync(validatedPath)) {
        throw this.createError(
          'File not found',
          'FILE_NOT_FOUND',
          { path: validatedPath }
        );
      }

      const stats = statSync(validatedPath);
      if (stats.isDirectory()) {
        throw this.createError(
          'Cannot read directory as file',
          'IS_DIRECTORY',
          { path: validatedPath }
        );
      }

      const content = readFileSync(validatedPath, 'utf-8');

      return {
        path: validatedPath,
        content,
        encoding: 'utf-8',
      };
    } catch (error) {
      if (error instanceof Error && 'code' in error) {
        throw error; // Re-throw our custom errors
      }
      throw this.createError(
        'Failed to read file',
        'READ_ERROR',
        { path, originalError: error instanceof Error ? error.message : String(error) }
      );
    }
  }

  /**
   * Write file content with automatic backup
   */
  public writeFile(path: string, content: string, createBackup = true): string {
    try {
      const validatedPath = this.validatePath(path);

      // Ensure directory exists
      const dir = dirname(validatedPath);
      if (!existsSync(dir)) {
        mkdirSync(dir, { recursive: true });
      }

      // Create backup if file exists and backup is enabled
      let backupContent: string | null = null;
      if (createBackup && existsSync(validatedPath)) {
        try {
          backupContent = readFileSync(validatedPath, 'utf-8');
        } catch (error) {
          console.warn('Failed to create backup:', error);
        }
      }

      // Write new content
      writeFileSync(validatedPath, content, 'utf-8');

      return validatedPath;
    } catch (error) {
      if (error instanceof Error && 'code' in error) {
        throw error;
      }
      throw this.createError(
        'Failed to write file',
        'WRITE_ERROR',
        { path, originalError: error instanceof Error ? error.message : String(error) }
      );
    }
  }

  /**
   * Check if a file exists
   */
  public fileExists(path: string): boolean {
    try {
      const validatedPath = this.validatePath(path);
      return existsSync(validatedPath);
    } catch {
      return false;
    }
  }

  /**
   * Delete a file
   */
  public deleteFile(path: string): boolean {
    try {
      const validatedPath = this.validatePath(path);

      if (!existsSync(validatedPath)) {
        return false;
      }

      const { unlinkSync } = await import('fs');
      unlinkSync(validatedPath);
      return true;
    } catch (error) {
      throw this.createError(
        'Failed to delete file',
        'DELETE_ERROR',
        { path, originalError: error instanceof Error ? error.message : String(error) }
      );
    }
  }

  /**
   * Get file stats
   */
  public getFileStats(path: string) {
    try {
      const validatedPath = this.validatePath(path);

      if (!existsSync(validatedPath)) {
        throw this.createError(
          'File not found',
          'FILE_NOT_FOUND',
          { path: validatedPath }
        );
      }

      const stats = statSync(validatedPath);
      return {
        size: stats.size,
        modified: stats.mtime,
        created: stats.birthtime,
        isDirectory: stats.isDirectory(),
        isFile: stats.isFile(),
      };
    } catch (error) {
      if (error instanceof Error && 'code' in error) {
        throw error;
      }
      throw this.createError(
        'Failed to get file stats',
        'STATS_ERROR',
        { path, originalError: error instanceof Error ? error.message : String(error) }
      );
    }
  }

  /**
   * Create a formatted error object
   */
  private createError(message: string, code?: string, details?: unknown): Error & ErrorResponse {
    const error = new Error(message) as Error & ErrorResponse;
    error.code = code;
    error.details = details;
    return error;
  }

  /**
   * Format error for consistent API responses
   */
  public static handleError(error: unknown): ErrorResponse {
    if (error instanceof Error && 'code' in error) {
      const customError = error as Error & ErrorResponse;
      return {
        error: customError.message,
        code: customError.code,
        details: customError.details,
      };
    }

    if (error instanceof Error) {
      return {
        error: error.message,
        code: 'UNKNOWN_ERROR',
      };
    }

    return {
      error: String(error),
      code: 'UNKNOWN_ERROR',
    };
  }

  /**
   * Get the base path
   */
  public getBasePath(): string {
    return this.basePath;
  }
}

/**
 * changeJournal.ts - Undo/rollback system for file operations
 *
 * Features:
 * - Record every write operation with timestamp, path, oldContent, newContent
 * - Retrieve individual changes
 * - Rollback to oldContent
 * - List all recorded changes
 */

import { randomUUID } from 'crypto';
import type { ChangeRecord, WriteOperation } from './types.js';

export class ChangeJournal {
  private changes: Map<string, ChangeRecord> = new Map();
  private maxChanges: number = 1000; // Prevent unbounded memory growth

  /**
   * Record a write operation in the journal
   */
  public record(operation: WriteOperation): ChangeRecord {
    const record: ChangeRecord = {
      id: randomUUID(),
      ...operation,
    };

    this.changes.set(record.id, record);

    // Prevent unbounded growth
    if (this.changes.size > this.maxChanges) {
      // Remove oldest entry (first in Map iteration order)
      const firstKey = this.changes.keys().next().value;
      if (firstKey) {
        this.changes.delete(firstKey);
      }
    }

    return record;
  }

  /**
   * Get a specific change by ID
   */
  public getChange(id: string): ChangeRecord | undefined {
    return this.changes.get(id);
  }

  /**
   * Rollback a change - returns the old content that should be restored
   */
  public rollbackChange(id: string): { path: string; content: string | null } | undefined {
    const change = this.changes.get(id);
    if (!change) {
      return undefined;
    }

    return {
      path: change.path,
      content: change.oldContent,
    };
  }

  /**
   * List all recorded changes, optionally filtered
   */
  public listChanges(options?: {
    limit?: number;
    offset?: number;
    path?: string;
  }): ChangeRecord[] {
    let changes = Array.from(this.changes.values());

    // Sort by timestamp descending (newest first)
    changes.sort((a, b) => b.timestamp - a.timestamp);

    // Filter by path if specified
    if (options?.path) {
      changes = changes.filter(change =>
        change.path.includes(options.path!)
      );
    }

    // Apply offset
    if (options?.offset) {
      changes = changes.slice(options.offset);
    }

    // Apply limit
    if (options?.limit) {
      changes = changes.slice(0, options.limit);
    }

    return changes;
  }

  /**
   * Get changes for a specific file
   */
  public getChangesForFile(path: string): ChangeRecord[] {
    return this.listChanges({ path });
  }

  /**
   * Clear all recorded changes
   */
  public clear(): void {
    this.changes.clear();
  }

  /**
   * Get total number of recorded changes
   */
  public size(): number {
    return this.changes.size;
  }

  /**
   * Remove a specific change from the journal
   */
  public remove(id: string): boolean {
    return this.changes.delete(id);
  }

  /**
   * Export all changes as JSON
   */
  public export(): string {
    const changes = Array.from(this.changes.values());
    return JSON.stringify(changes, null, 2);
  }

  /**
   * Import changes from JSON (replaces current journal)
   */
  public import(json: string): void {
    try {
      const changes = JSON.parse(json) as ChangeRecord[];
      this.changes.clear();

      for (const change of changes) {
        this.changes.set(change.id, change);
      }
    } catch (error) {
      throw new Error('Failed to import changes: invalid JSON format');
    }
  }
}

/**
 * taskStore.ts - SQLite database for task persistence
 *
 * Features:
 * - SQLite database initialization
 * - Tasks table with full schema
 * - CRUD operations
 * - Indexes on status and priority
 */

import { readFileSync, writeFileSync, existsSync } from 'fs';
import { resolve } from 'path';
import initSqlJs, { Database, SqlValue } from 'sql.js';
import type { Task, CreateTaskInput, UpdateTaskInput } from './types.js';

export class TaskStore {
  private db: Database | null = null;
  private dbPath: string;
  private isInitialized = false;

  constructor(dbPath: string) {
    this.dbPath = resolve(dbPath);
  }

  /**
   * Initialize SQLite database and create schema
   */
  public async initialize(): Promise<void> {
    if (this.isInitialized) {
      return;
    }

    try {
      // Initialize sql.js
      const SQL = await initSqlJs();

      // Load existing database or create new one
      if (existsSync(this.dbPath)) {
        const buffer = readFileSync(this.dbPath);
        this.db = new SQL.Buffer(buffer);
      } else {
        this.db = new SQL.Database();
        this.createSchema();
        await this.save();
      }

      this.isInitialized = true;
      console.log(`Task store initialized: ${this.dbPath}`);
    } catch (error) {
      throw new Error(`Failed to initialize task store: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  /**
   * Create database schema
   */
  private createSchema(): void {
    if (!this.db) {
      throw new Error('Database not initialized');
    }

    // Create tasks table
    this.db.run(`
      CREATE TABLE IF NOT EXISTS tasks (
        id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        description TEXT,
        status TEXT NOT NULL DEFAULT 'pending',
        priority TEXT NOT NULL DEFAULT 'medium',
        files TEXT,
        dependencies TEXT,
        createdAt INTEGER NOT NULL,
        updatedAt INTEGER NOT NULL
      )
    `);

    // Create indexes
    this.db.run(`
      CREATE INDEX IF NOT EXISTS idx_tasks_status
      ON tasks(status)
    `);

    this.db.run(`
      CREATE INDEX IF NOT EXISTS idx_tasks_priority
      ON tasks(priority)
    `);

    this.db.run(`
      CREATE INDEX IF NOT EXISTS idx_tasks_created_at
      ON tasks(createdAt)
    `);
  }

  /**
   * Save database to disk
   */
  private async save(): Promise<void> {
    if (!this.db) {
      throw new Error('Database not initialized');
    }

    const data = this.db.export();
    const buffer = Buffer.from(data);
    writeFileSync(this.dbPath, buffer);
  }

  /**
   * Ensure database is initialized
   */
  private ensureInitialized(): void {
    if (!this.isInitialized || !this.db) {
      throw new Error('Task store not initialized. Call initialize() first.');
    }
  }

  /**
   * Convert database row to Task object
   */
  private rowToTask(row: SqlValue[]): Task {
    return {
      id: String(row[0]),
      title: String(row[1]),
      description: String(row[2] ?? ''),
      status: String(row[3]) as Task['status'],
      priority: String(row[4]) as Task['priority'],
      files: row[5] ? JSON.parse(String(row[5])) : [],
      dependencies: row[6] ? JSON.parse(String(row[6])) : [],
      createdAt: Number(row[7]),
      updatedAt: Number(row[8]),
    };
  }

  /**
   * Create a new task
   */
  public async createTask(input: CreateTaskInput): Promise<Task> {
    this.ensureInitialized();

    const { randomUUID } = await import('crypto');
    const now = Date.now();

    const task: Task = {
      id: randomUUID(),
      title: input.title,
      description: input.description ?? '',
      status: input.status ?? 'pending',
      priority: input.priority ?? 'medium',
      files: input.files ?? [],
      dependencies: input.dependencies ?? [],
      createdAt: now,
      updatedAt: now,
    };

    if (!this.db) {
      throw new Error('Database not initialized');
    }

    this.db.run(
      `INSERT INTO tasks (id, title, description, status, priority, files, dependencies, createdAt, updatedAt)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        task.id,
        task.title,
        task.description,
        task.status,
        task.priority,
        JSON.stringify(task.files),
        JSON.stringify(task.dependencies),
        task.createdAt,
        task.updatedAt,
      ]
    );

    await this.save();
    return task;
  }

  /**
   * Get a task by ID
   */
  public getTask(id: string): Task | undefined {
    this.ensureInitialized();

    if (!this.db) {
      throw new Error('Database not initialized');
    }

    const stmt = this.db.prepare('SELECT * FROM tasks WHERE id = ?');
    stmt.bind([id]);
    const result = stmt.getAsObject() as Record<string, SqlValue>;
    stmt.free();

    if (!result || Object.keys(result).length === 0) {
      return undefined;
    }

    return this.rowToTask(Object.values(result));
  }

  /**
   * Update a task
   */
  public async updateTask(id: string, input: UpdateTaskInput): Promise<Task | undefined> {
    this.ensureInitialized();

    const existing = this.getTask(id);
    if (!existing) {
      return undefined;
    }

    const updated: Task = {
      ...existing,
      title: input.title ?? existing.title,
      description: input.description ?? existing.description,
      status: input.status ?? existing.status,
      priority: input.priority ?? existing.priority,
      files: input.files ?? existing.files,
      dependencies: input.dependencies ?? existing.dependencies,
      updatedAt: Date.now(),
    };

    if (!this.db) {
      throw new Error('Database not initialized');
    }

    this.db.run(
      `UPDATE tasks
       SET title = ?, description = ?, status = ?, priority = ?, files = ?, dependencies = ?, updatedAt = ?
       WHERE id = ?`,
      [
        updated.title,
        updated.description,
        updated.status,
        updated.priority,
        JSON.stringify(updated.files),
        JSON.stringify(updated.dependencies),
        updated.updatedAt,
        id,
      ]
    );

    await this.save();
    return updated;
  }

  /**
   * Delete a task
   */
  public async deleteTask(id: string): Promise<boolean> {
    this.ensureInitialized();

    const existing = this.getTask(id);
    if (!existing) {
      return false;
    }

    if (!this.db) {
      throw new Error('Database not initialized');
    }

    this.db.run('DELETE FROM tasks WHERE id = ?', [id]);
    await this.save();
    return true;
  }

  /**
   * List all tasks with optional filtering
   */
  public listTasks(filters?: {
    status?: Task['status'];
    priority?: Task['priority'];
    limit?: number;
    offset?: number;
  }): Task[] {
    this.ensureInitialized();

    if (!this.db) {
      throw new Error('Database not initialized');
    }

    let query = 'SELECT * FROM tasks';
    const params: SqlValue[] = [];

    // Build WHERE clause
    const conditions: string[] = [];
    if (filters?.status) {
      conditions.push('status = ?');
      params.push(filters.status);
    }
    if (filters?.priority) {
      conditions.push('priority = ?');
      params.push(filters.priority);
    }

    if (conditions.length > 0) {
      query += ' WHERE ' + conditions.join(' AND ');
    }

    // Add sorting and pagination
    query += ' ORDER BY createdAt DESC';

    if (filters?.limit) {
      query += ' LIMIT ?';
      params.push(filters.limit);
    }

    if (filters?.offset) {
      query += ' OFFSET ?';
      params.push(filters.offset);
    }

    const stmt = this.db.prepare(query);
    stmt.bind(params);
    const results: Task[] = [];

    while (stmt.step()) {
      const row = stmt.getAsObject() as Record<string, SqlValue>;
      results.push(this.rowToTask(Object.values(row)));
    }

    stmt.free();
    return results;
  }

  /**
   * Get task count by status
   */
  public getTaskCountByStatus(): Record<string, number> {
    this.ensureInitialized();

    if (!this.db) {
      throw new Error('Database not initialized');
    }

    const stmt = this.db.prepare(`
      SELECT status, COUNT(*) as count
      FROM tasks
      GROUP BY status
    `);

    const result: Record<string, number> = {};

    while (stmt.step()) {
      const row = stmt.getAsObject() as Record<string, SqlValue>;
      result[String(row.status)] = Number(row.count);
    }

    stmt.free();
    return result;
  }

  /**
   * Close the database connection
   */
  public close(): void {
    if (this.db) {
      this.db.close();
      this.db = null;
      this.isInitialized = false;
    }
  }
}

/**
 * WebSocket server for real-time updates
 *
 * Features:
 * - WebSocket server on separate port
 * - Broadcast events: file:changed, file:added, file:deleted, task:updated
 * - Client connection management
 */

import { WebSocketServer, WebSocket } from 'ws';
import type { Server as HTTPServer } from 'http';
import type { WebSocketMessage, FileEvent, Task } from './types.js';

export class WebSocketServerManager {
  private wss: WebSocketServer | null = null;
  private port: number;
  private clients: Set<WebSocket> = new Set();

  constructor(port: number = 3001) {
    this.port = port;
  }

  /**
   * Start the WebSocket server
   */
  public start(server?: HTTPServer): void {
    if (this.wss) {
      throw new Error('WebSocket server is already running');
    }

    this.wss = new WebSocketServer({
      port: server ? undefined : this.port,
      server,
    });

    this.wss.on('connection', (ws: WebSocket) => {
      console.log('WebSocket client connected');
      this.clients.add(ws);

      // Send welcome message
      this.sendToClient(ws, {
        type: 'error',
        data: { message: 'Connected to CodeBaseCartographer server' },
        timestamp: Date.now(),
      });

      ws.on('message', (data: Buffer) => {
        try {
          const message = JSON.parse(data.toString()) as WebSocketMessage;
          this.handleMessage(ws, message);
        } catch (error) {
          console.error('Failed to parse WebSocket message:', error);
        }
      });

      ws.on('close', () => {
        console.log('WebSocket client disconnected');
        this.clients.delete(ws);
      });

      ws.on('error', (error) => {
        console.error('WebSocket error:', error);
        this.clients.delete(ws);
      });
    });

    console.log(`WebSocket server listening on port ${this.port}`);
  }

  /**
   * Handle incoming message from client
   */
  private handleMessage(ws: WebSocket, message: WebSocketMessage): void {
    // Currently we don't process client messages, but this is where
    // we would handle client requests like "subscribe to path"
    console.log('Received message from client:', message.type);
  }

  /**
   * Stop the WebSocket server
   */
  public stop(): void {
    if (this.wss) {
      // Close all client connections
      this.clients.forEach(client => {
        if (client.readyState === WebSocket.OPEN) {
          client.close();
        }
      });
      this.clients.clear();

      this.wss.close();
      this.wss = null;
      console.log('WebSocket server stopped');
    }
  }

  /**
   * Broadcast a file event to all connected clients
   */
  public broadcastFileEvent(event: FileEvent): void {
    const messageType = {
      add: 'file:added',
      change: 'file:changed',
      unlink: 'file:deleted',
    }[event.type];

    this.broadcast({
      type: messageType,
      data: {
        path: event.path,
        timestamp: event.timestamp,
      },
      timestamp: Date.now(),
    });
  }

  /**
   * Broadcast a task update to all connected clients
   */
  public broadcastTaskUpdate(task: Task): void {
    this.broadcast({
      type: 'task:updated',
      data: task,
      timestamp: Date.now(),
    });
  }

  /**
   * Broadcast a generic error to all connected clients
   */
  public broadcastError(error: string, details?: unknown): void {
    this.broadcast({
      type: 'error',
      data: { error, details },
      timestamp: Date.now(),
    });
  }

  /**
   * Broadcast a message to all connected clients
   */
  private broadcast(message: WebSocketMessage): void {
    const data = JSON.stringify(message);

    this.clients.forEach(client => {
      if (client.readyState === WebSocket.OPEN) {
        try {
          client.send(data);
        } catch (error) {
          console.error('Failed to send message to client:', error);
          this.clients.delete(client);
        }
      }
    });
  }

  /**
   * Send a message to a specific client
   */
  private sendToClient(ws: WebSocket, message: WebSocketMessage): void {
    if (ws.readyState === WebSocket.OPEN) {
      try {
        ws.send(JSON.stringify(message));
      } catch (error) {
        console.error('Failed to send message to client:', error);
      }
    }
  }

  /**
   * Get the number of connected clients
   */
  public getClientCount(): number {
    return this.clients.size;
  }

  /**
   * Check if server is running
   */
  public isRunning(): boolean {
    return this.wss !== null;
  }
}

/**
 * server.ts - Main Express server with REST API
 *
 * Features:
 * - REST API endpoints for files, tasks, and changes
 * - WebSocket server for real-time updates
 * - File watching integration
 * - Error handling middleware
 */

import express, { Request, Response, NextFunction } from 'express';
import cors from 'cors';
import { createServer } from 'http';
import { resolve } from 'path';
import { FileWatcher } from './fileWatcher.js';
import { FileOperator } from './fileOperator.js';
import { ChangeJournal } from './changeJournal.js';
import { TaskStore } from './taskStore.js';
import { WebSocketServerManager } from './webSocketServer.js';
import type { CreateTaskInput, UpdateTaskInput } from './types.js';

export class Server {
  private app: express.Application;
  private httpServer: ReturnType<typeof createServer>;
  private port: number;
  private wsPort: number;
  private watchPath: string;
  private dbPath: string;

  private fileWatcher: FileWatcher;
  private fileOperator: FileOperator;
  private changeJournal: ChangeJournal;
  private taskStore: TaskStore;
  private wsManager: WebSocketServerManager;

  constructor(
    port: number = 3000,
    wsPort: number = 3001,
    watchPath: string = process.cwd(),
    dbPath: string = './tasks.db'
  ) {
    this.port = port;
    this.wsPort = wsPort;
    this.watchPath = resolve(watchPath);
    this.dbPath = resolve(dbPath);

    this.app = express();
    this.httpServer = createServer(this.app);

    // Initialize components
    this.fileWatcher = new FileWatcher(this.watchPath);
    this.fileOperator = new FileOperator(this.watchPath);
    this.changeJournal = new ChangeJournal();
    this.taskStore = new TaskStore(this.dbPath);
    this.wsManager = new WebSocketServerManager(wsPort);

    this.setupMiddleware();
    this.setupRoutes();
    this.setupErrorHandling();
  }

  /**
   * Setup Express middleware
   */
  private setupMiddleware(): void {
    this.app.use(cors());
    this.app.use(express.json());
    this.app.use((req, res, next) => {
      console.log(`${req.method} ${req.path}`);
      next();
    });
  }

  /**
   * Setup REST API routes
   */
  private setupRoutes(): void {
    // Health check
    this.app.get('/api/health', (req, res) => {
      res.json({
        status: 'ok',
        watchPath: this.watchPath,
        timestamp: Date.now(),
      });
    });

    // File routes
    this.app.get('/api/files', this.listFiles.bind(this));
    this.app.get('/api/files/*', this.readFile.bind(this));
    this.app.post('/api/files/*', this.writeFile.bind(this));
    this.app.delete('/api/files/*', this.deleteFile.bind(this));

    // Task routes
    this.app.get('/api/tasks', this.listTasks.bind(this));
    this.app.post('/api/tasks', this.createTask.bind(this));
    this.app.get('/api/tasks/:id', this.getTask.bind(this));
    this.app.put('/api/tasks/:id', this.updateTask.bind(this));
    this.app.delete('/api/tasks/:id', this.deleteTask.bind(this));
    this.app.get('/api/tasks/stats/summary', this.getTaskStats.bind(this));

    // Change journal routes
    this.app.get('/api/changes', this.listChanges.bind(this));
    this.app.get('/api/changes/:id', this.getChange.bind(this));
    this.app.post('/api/changes/:id/rollback', this.rollbackChange.bind(this));
  }

  /**
   * Setup error handling middleware
   */
  private setupErrorHandling(): void {
    this.app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
      console.error('Error:', err);
      const errorResponse = FileOperator.handleError(err);
      res.status(500).json(errorResponse);
    });
  }

  /**
   * GET /api/files - List watched files
   */
  private listFiles(req: Request, res: Response): void {
    try {
      const paths = this.fileWatcher.getWatchedPaths();
      res.json({
        files: paths,
        count: paths.length,
      });
    } catch (error) {
      res.status(500).json(FileOperator.handleError(error));
    }
  }

  /**
   * GET /api/files/:path - Read file content
   */
  private readFile(req: Request, res: Response): void {
    try {
      const path = req.params[0];
      const file = this.fileOperator.readFile(path);
      res.json(file);
    } catch (error) {
      res.status(500).json(FileOperator.handleError(error));
    }
  }

  /**
   * POST /api/files/:path - Write file content
   */
  private writeFile(req: Request, res: Response): void {
    try {
      const path = req.params[0];
      const { content } = req.body;

      if (typeof content !== 'string') {
        res.status(400).json({ error: 'Content must be a string' });
        return;
      }

      // Record old content for change journal
      let oldContent: string | null = null;
      try {
        const existingFile = this.fileOperator.readFile(path);
        oldContent = existingFile.content;
      } catch {
        // File doesn't exist, that's okay
      }

      // Write file
      const writtenPath = this.fileOperator.writeFile(path, content);

      // Record in change journal
      this.changeJournal.record({
        path: writtenPath,
        oldContent,
        newContent: content,
        timestamp: Date.now(),
      });

      res.json({
        path: writtenPath,
        message: 'File written successfully',
      });
    } catch (error) {
      res.status(500).json(FileOperator.handleError(error));
    }
  }

  /**
   * DELETE /api/files/:path - Delete a file
   */
  private deleteFile(req: Request, res: Response): void {
    try {
      const path = req.params[0];
      const deleted = this.fileOperator.deleteFile(path);

      if (!deleted) {
        res.status(404).json({ error: 'File not found' });
        return;
      }

      res.json({
        path,
        message: 'File deleted successfully',
      });
    } catch (error) {
      res.status(500).json(FileOperator.handleError(error));
    }
  }

  /**
   * GET /api/tasks - List tasks
   */
  private async listTasks(req: Request, res: Response): Promise<void> {
    try {
      const { status, priority, limit, offset } = req.query;

      const tasks = this.taskStore.listTasks({
        status: status as any,
        priority: priority as any,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });

      res.json({
        tasks,
        count: tasks.length,
      });
    } catch (error) {
      res.status(500).json(FileOperator.handleError(error));
    }
  }

  /**
   * POST /api/tasks - Create task
   */
  private async createTask(req: Request, res: Response): Promise<void> {
    try {
      const input = req.body as CreateTaskInput;

      if (!input.title) {
        res.status(400).json({ error: 'Title is required' });
        return;
      }

      const task = await this.taskStore.createTask(input);

      // Broadcast update
      this.wsManager.broadcastTaskUpdate(task);

      res.status(201).json(task);
    } catch (error) {
      res.status(500).json(FileOperator.handleError(error));
    }
  }

  /**
   * GET /api/tasks/:id - Get task
   */
  private getTask(req: Request, res: Response): void {
    try {
      const { id } = req.params;
      const task = this.taskStore.getTask(id);

      if (!task) {
        res.status(404).json({ error: 'Task not found' });
        return;
      }

      res.json(task);
    } catch (error) {
      res.status(500).json(FileOperator.handleError(error));
    }
  }

  /**
   * PUT /api/tasks/:id - Update task
   */
  private async updateTask(req: Request, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const input = req.body as UpdateTaskInput;

      const task = await this.taskStore.updateTask(id, input);

      if (!task) {
        res.status(404).json({ error: 'Task not found' });
        return;
      }

      // Broadcast update
      this.wsManager.broadcastTaskUpdate(task);

      res.json(task);
    } catch (error) {
      res.status(500).json(FileOperator.handleError(error));
    }
  }

  /**
   * DELETE /api/tasks/:id - Delete task
   */
  private async deleteTask(req: Request, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const deleted = await this.taskStore.deleteTask(id);

      if (!deleted) {
        res.status(404).json({ error: 'Task not found' });
        return;
      }

      res.json({ message: 'Task deleted successfully' });
    } catch (error) {
      res.status(500).json(FileOperator.handleError(error));
    }
  }

  /**
   * GET /api/tasks/stats/summary - Get task statistics
   */
  private getTaskStats(req: Request, res: Response): void {
    try {
      const stats = this.taskStore.getTaskCountByStatus();
      res.json(stats);
    } catch (error) {
      res.status(500).json(FileOperator.handleError(error));
    }
  }

  /**
   * GET /api/changes - List change journal
   */
  private listChanges(req: Request, res: Response): void {
    try {
      const { limit, offset, path } = req.query;

      const changes = this.changeJournal.listChanges({
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
        path: path as string | undefined,
      });

      res.json({
        changes,
        count: changes.length,
      });
    } catch (error) {
      res.status(500).json(FileOperator.handleError(error));
    }
  }

  /**
   * GET /api/changes/:id - Get change
   */
  private getChange(req: Request, res: Response): void {
    try {
      const { id } = req.params;
      const change = this.changeJournal.getChange(id);

      if (!change) {
        res.status(404).json({ error: 'Change not found' });
        return;
      }

      res.json(change);
    } catch (error) {
      res.status(500).json(FileOperator.handleError(error));
    }
  }

  /**
   * POST /api/changes/:id/rollback - Rollback a change
   */
  private rollbackChange(req: Request, res: Response): void {
    try {
      const { id } = req.params;
      const rollback = this.changeJournal.rollbackChange(id);

      if (!rollback) {
        res.status(404).json({ error: 'Change not found' });
        return;
      }

      // Restore old content
      if (rollback.content !== null) {
        this.fileOperator.writeFile(rollback.path, rollback.content, false);
      } else {
        // File didn't exist before, delete it
        this.fileOperator.deleteFile(rollback.path);
      }

      res.json({
        message: 'Change rolled back successfully',
        path: rollback.path,
      });
    } catch (error) {
      res.status(500).json(FileOperator.handleError(error));
    }
  }

  /**
   * Start the server
   */
  public async start(): Promise<void> {
    try {
      // Initialize task store
      await this.taskStore.initialize();

      // Start file watcher
      this.fileWatcher.start();

      // Setup file event handler to broadcast changes
      this.fileWatcher.onFileEvent((event) => {
        this.wsManager.broadcastFileEvent(event);
      });

      // Start WebSocket server
      this.wsManager.start(this.httpServer);

      // Start HTTP server
      this.httpServer.listen(this.port, () => {
        console.log(`HTTP server listening on port ${this.port}`);
        console.log(`WebSocket server listening on port ${this.wsPort}`);
        console.log(`Watching directory: ${this.watchPath}`);
      });
    } catch (error) {
      console.error('Failed to start server:', error);
      throw error;
    }
  }

  /**
   * Stop the server
   */
  public stop(): void {
    this.fileWatcher.stop();
    this.wsManager.stop();
    this.taskStore.close();
    this.httpServer.close();
    console.log('Server stopped');
  }
}

/**
 * Entry point for CodeBaseCartographer server
 */

import { Server } from './server.js';

async function main() {
  const PORT = process.env.PORT ? Number.parseInt(process.env.PORT) : 3000;
  const WS_PORT = process.env.WS_PORT ? Number.parseInt(process.env.WS_PORT) : 3001;
  const WATCH_PATH = process.env.WATCH_PATH || process.cwd();
  const DB_PATH = process.env.DB_PATH || './tasks.db';

  const server = new Server(PORT, WS_PORT, WATCH_PATH, DB_PATH);

  // Handle graceful shutdown
  process.on('SIGINT', () => {
    console.log('\nReceived SIGINT, shutting down gracefully...');
    server.stop();
    process.exit(0);
  });

  process.on('SIGTERM', () => {
    console.log('\nReceived SIGTERM, shutting down gracefully...');
    server.stop();
    process.exit(0);
  });

  try {
    await server.start();
  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
}

main();

